plugins {
    // Apply the application plugin to add support for building a CLI application in Java.
    application
}

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

dependencies {
    // Use JUnit Jupiter for testing.
    testImplementation(libs.junit.jupiter)
    implementation(libs.jackson.databind)
    implementation(libs.sqlite.jdbc)//these two lines are for checking if our packages compile and are 'healthy'. not testImplementation because that doesnt bundle it aswell
    testRuntimeOnly("org.junit.platform:junit-platform-launcher")

}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(17)
    }
}

application {
    // Define the main class for the application.
    mainClass = "logger.Main"
}

tasks.named<Test>("test") {
    // Use JUnit Platform for unit tests.
    useJUnitPlatform()
}

tasks.named<JavaExec>("run"){//simple func to auto load .env into terminal when runnning/testing
    val envFile = rootProject.file("../.env")
    if(envFile.exists()){
        envFile.readLines().forEach {line ->
            val w = line.trim()
            if(w.isEmpty() || w.startsWith('#') || w.startsWith("//")) return@forEach
            val parts = w.split('=', limit =2)//cos we got the name on one side jey on the other
            if(parts.size == 2) environment(parts[0].trim(), parts[1].trim())
        }
    }
}
